#!/usr/bin/env bash
# Files docs/issues/*.md as GitHub issues. Needs `gh auth login` on this machine. Re-running skips titles that already exist.
set -euo pipefail
REPO="${1:-mayurrawte/fitdash}"
cd "$(dirname "$0")/.."
for l in must-have good-to-have widget data scores sync insights sleep today alerts activity theme modules accessibility; do gh label create "$l" --repo "$REPO" --force >/dev/null 2>&1 || true; done
existing=$(gh issue list --repo "$REPO" --state all --limit 200 --json title --jq '.[].title')
if grep -Fxq "Home screen widget with recovery, sleep and steps" <<< "$existing"; then echo "skip: Home screen widget with recovery, sleep and steps"; else gh issue create --repo "$REPO" --title "Home screen widget with recovery, sleep and steps" --label "must-have" --label "widget" --body-file "docs/issues/01-widget-home-screen-widget-with-recovery-sleep-and-steps.md"; fi
if grep -Fxq "CSV export of the daily table and of raw series" <<< "$existing"; then echo "skip: CSV export of the daily table and of raw series"; else gh issue create --repo "$REPO" --title "CSV export of the daily table and of raw series" --label "must-have" --label "data" --body-file "docs/issues/02-data-csv-export-of-the-daily-table-and-of-raw-series.md"; fi
if grep -Fxq "Contributors for every score, Oura and Ultrahuman style" <<< "$existing"; then echo "skip: Contributors for every score, Oura and Ultrahuman style"; else gh issue create --repo "$REPO" --title "Contributors for every score, Oura and Ultrahuman style" --label "must-have" --label "scores" --body-file "docs/issues/03-scores-contributors-for-every-score-oura-and-ultrahuman-s.md"; fi
if grep -Fxq "Explain missing data per watch instead of showing an empty tile" <<< "$existing"; then echo "skip: Explain missing data per watch instead of showing an empty tile"; else gh issue create --repo "$REPO" --title "Explain missing data per watch instead of showing an empty tile" --label "must-have" --label "sync" --body-file "docs/issues/04-sync-explain-missing-data-per-watch-instead-of-showing-.md"; fi
if grep -Fxq "Sync reminder and background refresh so the data is fresh when the app opens" <<< "$existing"; then echo "skip: Sync reminder and background refresh so the data is fresh when the app opens"; else gh issue create --repo "$REPO" --title "Sync reminder and background refresh so the data is fresh when the app opens" --label "must-have" --label "sync" --body-file "docs/issues/05-sync-sync-reminder-and-background-refresh-so-the-data-i.md"; fi
if grep -Fxq "Journal tags with correlations" <<< "$existing"; then echo "skip: Journal tags with correlations"; else gh issue create --repo "$REPO" --title "Journal tags with correlations" --label "good-to-have" --label "insights" --body-file "docs/issues/06-insights-journal-tags-with-correlations.md"; fi
if grep -Fxq "Weekly review card with week-over-week comparison" <<< "$existing"; then echo "skip: Weekly review card with week-over-week comparison"; else gh issue create --repo "$REPO" --title "Weekly review card with week-over-week comparison" --label "good-to-have" --label "insights" --body-file "docs/issues/07-insights-weekly-review-card-with-week-over-week-comparison.md"; fi
if grep -Fxq "Sleep debt, bedtime consistency and a bedtime target" <<< "$existing"; then echo "skip: Sleep debt, bedtime consistency and a bedtime target"; else gh issue create --repo "$REPO" --title "Sleep debt, bedtime consistency and a bedtime target" --label "good-to-have" --label "sleep" --body-file "docs/issues/08-sleep-sleep-debt-bedtime-consistency-and-a-bedtime-targe.md"; fi
if grep -Fxq "Day timeline with sleep, workouts, heart rate and caffeine cut-off" <<< "$existing"; then echo "skip: Day timeline with sleep, workouts, heart rate and caffeine cut-off"; else gh issue create --repo "$REPO" --title "Day timeline with sleep, workouts, heart rate and caffeine cut-off" --label "good-to-have" --label "today" --body-file "docs/issues/09-today-day-timeline-with-sleep-workouts-heart-rate-and-ca.md"; fi
if grep -Fxq "Morning out-of-range alert for overnight vitals" <<< "$existing"; then echo "skip: Morning out-of-range alert for overnight vitals"; else gh issue create --repo "$REPO" --title "Morning out-of-range alert for overnight vitals" --label "good-to-have" --label "alerts" --body-file "docs/issues/10-alerts-morning-out-of-range-alert-for-overnight-vitals.md"; fi
if grep -Fxq "Heart-rate zones per workout and zone minutes per day" <<< "$existing"; then echo "skip: Heart-rate zones per workout and zone minutes per day"; else gh issue create --repo "$REPO" --title "Heart-rate zones per workout and zone minutes per day" --label "good-to-have" --label "activity" --body-file "docs/issues/11-activity-heart-rate-zones-per-workout-and-zone-minutes-per-.md"; fi
if grep -Fxq "Material You dynamic colour as a third theme" <<< "$existing"; then echo "skip: Material You dynamic colour as a third theme"; else gh issue create --repo "$REPO" --title "Material You dynamic colour as a third theme" --label "good-to-have" --label "theme" --body-file "docs/issues/12-theme-material-you-dynamic-colour-as-a-third-theme.md"; fi
if grep -Fxq "Cycle tracking module, opt-in" <<< "$existing"; then echo "skip: Cycle tracking module, opt-in"; else gh issue create --repo "$REPO" --title "Cycle tracking module, opt-in" --label "good-to-have" --label "modules" --body-file "docs/issues/13-modules-cycle-tracking-module-opt-in.md"; fi
if grep -Fxq "Accessibility pass: TalkBack order, 1.3x font scale, reduce motion by system setting" <<< "$existing"; then echo "skip: Accessibility pass: TalkBack order, 1.3x font scale, reduce motion by system setting"; else gh issue create --repo "$REPO" --title "Accessibility pass: TalkBack order, 1.3x font scale, reduce motion by system setting" --label "good-to-have" --label "accessibility" --body-file "docs/issues/14-accessibility-accessibility-pass-talkback-order-1.3x-font-scale-.md"; fi
